/**
 * UI/Components/ItemFinder/ItemFinder.js
 *
 * Turoran Item Finder: search weapons / armor / cards by stats and effects.
 * Data: System/itemfinder.turoran.v1.json (generated by turoran-ro-grf generators/genitemfinder.py)
 */

import DB from 'DB/DBManager.js';
import Client from 'Core/Client.js';
import KEYS from 'Controls/KeyEventHandler.js';
import GUIComponent from 'UI/GUIComponent.js';
import UIManager from 'UI/UIManager.js';
import ItemInfo from 'UI/Components/ItemInfo/ItemInfo.js';
import 'UI/Elements/Elements.js';
import htmlText from './ItemFinder.html?raw';
import cssText from './ItemFinder.css?raw';

const DATA_FILE = 'System/itemfinder.turoran.v1.json';
const PAGE = 60;
const KINDS = [
	['damage', '% Damage'],
	['resist', '% Resist'],
	['attr', '+Stat'],
	['def', 'DEF'],
	['mdef', 'MDEF'],
	['hpsp', 'HP/SP'],
	['aspd', 'ASPD'],
	['cast', 'Cast'],
	['crit', 'Crit'],
	['hitflee', 'Hit/Flee'],
	['heal', 'Heal'],
	['autospell', 'Autospell'],
	['other', 'Other']
];

const ItemFinder = new GUIComponent('ItemFinder', cssText);
ItemFinder.render = () => htmlText;

let _items = null;
let _loading = false;
let _cat = 'weapon';
let _page = 0;
let _results = [];

function esc(s) {
	return String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
}

function mdefOf(it) {
	let m = 0;
	for (const e of it.eff) if (e.k === 'mdef' && e.t === 'MDEF' && typeof e.v === 'number') m += e.v;
	return m;
}

function loadData(cb) {
	if (_items) return cb();
	if (_loading) return;
	_loading = true;
	setStatus('Loading item data...');
	Client.getFile(
		DATA_FILE,
		data => {
			try {
				const txt =
					typeof data === 'string'
						? data
						: new TextDecoder('utf-8').decode(data instanceof ArrayBuffer ? new Uint8Array(data) : data);
				_items = JSON.parse(txt).items;
				for (const it of _items) {
					it._mdef = mdefOf(it);
					it._lc = (it.n + ' ' + it.eff.map(e => e.x).join(' ')).toLowerCase();
				}
			} catch (e) {
				setStatus('Failed to parse ' + DATA_FILE + ': ' + e.message);
			}
			_loading = false;
			cb();
		},
		() => {
			_loading = false;
			setStatus('Could not load ' + DATA_FILE);
		}
	);
}

function setStatus(t) {
	const root = ItemFinder.getRoot && ItemFinder.__loaded ? ItemFinder.getRoot() : null;
	if (root) root.querySelector('.status').textContent = t;
}

function fillSub() {
	const root = ItemFinder.getRoot();
	const sel = root.querySelector('.sub');
	const set = new Set();
	for (const it of _items || []) {
		if (it.c !== _cat) continue;
		if (_cat === 'weapon') set.add(it.wt);
		else for (const l of it.loc) set.add(l);
	}
	const label = { weapon: 'All weapon types', armor: 'All armor slots', card: 'All compound locations' }[_cat];
	sel.innerHTML =
		`<option value="">${label}</option>` +
		[...set]
			.sort()
			.map(v => `<option>${esc(v)}</option>`)
			.join('');
}

function matches(e, kinds, target) {
	if (kinds.size && !kinds.has(e.k)) return false;
	if (target && !(String(e.t).toLowerCase().includes(target) || e.x.toLowerCase().includes(target))) return false;
	return kinds.size > 0 || !!target;
}

ItemFinder.search = function search() {
	if (!_items) return;
	const root = this.getRoot();
	const q = root.querySelector('.q').value.trim().toLowerCase();
	const sub = root.querySelector('.sub').value;
	const target = root.querySelector('.target').value.trim().toLowerCase();
	const nocond = root.querySelector('.nocond').checked;
	const job = root.querySelector('.job').value.trim().toLowerCase();
	const lv = parseInt(root.querySelector('.lv').value, 10);
	const sort = root.querySelector('.sort').value;
	const dir = root.querySelector('.dir').value === 'asc' ? 1 : -1;
	const kinds = new Set([...root.querySelectorAll('.kinds input:checked')].map(i => i.value));
	const effFilter = kinds.size > 0 || !!target;

	const out = [];
	for (const it of _items) {
		if (it.c !== _cat) continue;
		if (sub && (_cat === 'weapon' ? it.wt !== sub : !it.loc.includes(sub))) continue;
		if (q && !it._lc.includes(q)) continue;
		if (!isNaN(lv) && it.lv > lv) continue;
		if (job && !it.j.startsWith('Every Job') && !it.j.toLowerCase().includes(job)) continue;
		if (job && it.j.toLowerCase().includes('except ' + job)) continue;
		let hit = null;
		let best = -Infinity;
		if (effFilter) {
			hit = [];
			it.eff.forEach((e, i) => {
				if ((!nocond || !e.c) && matches(e, kinds, target)) {
					hit.push(i);
					if (typeof e.v === 'number' && e.v > best) best = e.v;
				}
			});
			if (!hit.length) continue;
		}
		out.push({ it, hit, best });
	}
	const key = {
		atk: r => r.it.atk || 0,
		matk: r => r.it.matk || 0,
		def: r => r.it.def || 0,
		mdef: r => r.it._mdef,
		wl: r => r.it.wl || 0,
		lv: r => r.it.lv,
		s: r => r.it.s,
		w: r => r.it.w,
		id: r => r.it.id,
		eff: r => (r.best === -Infinity ? -1e9 : r.best)
	}[sort];
	if (key) out.sort((a, b) => (key(a) - key(b)) * dir || a.it.n.localeCompare(b.it.n));
	else out.sort((a, b) => a.it.n.localeCompare(b.it.n));
	_results = out;
	_page = 0;
	renderPage();
};

function stats(it) {
	const s = [];
	if (it.c === 'weapon') s.push(it.wt, 'ATK ' + it.atk + (it.matk ? ' MATK ' + it.matk : ''), 'Wpn Lv ' + it.wl);
	if (it.c === 'armor') s.push(it.loc.join('/'), 'DEF ' + it.def + (it._mdef ? ' MDEF ' + it._mdef : ''));
	if (it.c === 'card') s.push(it.loc.join('/') || 'Card');
	if (it.c !== 'card') s.push('Slots ' + it.s);
	s.push('Wt ' + it.w);
	if (it.lv) s.push('Lv ' + it.lv);
	if (it.r === 0) s.push('Unrefinable');
	if (it.mvp) s.push('Slotted MVP version');
	return s.join(' · ');
}

function renderPage() {
	const root = ItemFinder.getRoot();
	const list = root.querySelector('.list');
	const pages = Math.max(1, Math.ceil(_results.length / PAGE));
	_page = Math.min(Math.max(0, _page), pages - 1);
	const slice = _results.slice(_page * PAGE, _page * PAGE + PAGE);
	list.innerHTML = slice
		.map(({ it, hit }) => {
			const effs = it.eff
				.map(
					(e, i) =>
						`<li class="${hit && hit.includes(i) ? 'hit' : ''}${e.c ? ' cond' : ''}">${esc(e.x)}${e.c ? ' (conditional)' : ''}</li>`
				)
				.join('');
			return (
				`<div class="item" data-id="${it.id}"><div class="icon"></div><div><div class="name">${esc(it.n)}` +
				(it.s && it.c !== 'card' ? ` [${it.s}]` : '') +
				` <span class="stats">#${it.id}</span></div><div class="stats">${esc(stats(it))}</div>` +
				`<div class="stats">${esc(it.j)}</div><ul class="effs">${effs}</ul></div></div>`
			);
		})
		.join('');
	list.scrollTop = 0;
	setStatus(`${_results.length} result(s)`);
	root.querySelector('.page').textContent = `${_page + 1} / ${pages}`;
	slice.forEach(({ it }) => {
		const info = DB.getItemInfo(it.id);
		if (!info || !info.identifiedResourceName) return;
		Client.loadFile(DB.INTERFACE_PATH + 'item/' + info.identifiedResourceName + '.bmp', url => {
			const el = list.querySelector(`.item[data-id="${it.id}"] .icon`);
			if (el) el.style.backgroundImage = `url(${url})`;
		});
	});
}

ItemFinder.init = function init() {
	const root = this.getRoot();
	root.querySelector('.kinds').innerHTML = KINDS.map(
		([k, l]) => `<label><input type="checkbox" value="${k}" /> ${l}</label>`
	).join('');
	root.querySelector('.close').addEventListener('click', () => this.toggle());
	root.querySelectorAll('.tab').forEach(t =>
		t.addEventListener('click', () => {
			root.querySelectorAll('.tab').forEach(x => x.classList.remove('active'));
			t.classList.add('active');
			_cat = t.dataset.cat;
			if (_items) {
				fillSub();
				this.search();
			}
		})
	);
	let timer = null;
	const deb = () => {
		clearTimeout(timer);
		timer = setTimeout(() => this.search(), 150);
	};
	root.querySelectorAll('input, select').forEach(el => {
		el.addEventListener(el.tagName === 'INPUT' && el.type !== 'checkbox' ? 'input' : 'change', deb);
		el.addEventListener('keydown', e => e.stopPropagation());
		el.addEventListener('mousedown', e => e.stopPropagation());
	});
	root.querySelector('.prev').addEventListener('click', () => {
		_page--;
		renderPage();
	});
	root.querySelector('.next').addEventListener('click', () => {
		_page++;
		renderPage();
	});
	root.querySelector('.list').addEventListener('click', e => {
		const row = e.target.closest('.item');
		if (!row) return;
		const id = parseInt(row.dataset.id, 10);
		if (ItemInfo.uid === id) {
			ItemInfo.remove();
			return;
		}
		ItemInfo.append();
		ItemInfo.uid = id;
		ItemInfo.setItem({ ITID: id, IsIdentified: 1, IsDamaged: 0, RefiningLevel: 0, slot: null });
	});
	this.draggable('.titlebar');
};

ItemFinder.onAppend = function onAppend() {
	loadData(() => {
		if (!_items) return;
		fillSub();
		this.search();
	});
};

ItemFinder.toggle = function toggle() {
	if (this.__active) this.remove();
	else this.append();
};

ItemFinder.onShortCut = function onShortCut(key) {
	if (key.cmd === 'TOGGLE') this.toggle();
};

ItemFinder.onKeyDown = function onKeyDown(event) {
	if ((event.which === KEYS.ESCAPE || event.key === 'Escape') && this.__active) {
		this.remove();
		event.stopImmediatePropagation();
		return false;
	}
	return true;
};

export default UIManager.addComponent(ItemFinder);
